package dev.aerove.lite.optics

import org.junit.Assert.assertEquals
import org.junit.Assert.assertFalse
import org.junit.Assert.assertTrue
import org.junit.Test
import kotlin.math.abs

class SuperellipseGeometryTest {
    // Flutter 3.47.6 round_superellipse_unittests.cc:641-658, not generated by this port.
    @Test fun officialUniformSquareContains() {
        val shape = AeroveSuperellipseGeometry.resolve(100.0, 100.0, 5.0)
        val points = listOf(OpticsPoint(0.0, 49.995), OpticsPoint(44.245, 49.95),
            OpticsPoint(45.72, 49.87), OpticsPoint(48.53, 48.53), OpticsPoint(49.87, 45.72),
            OpticsPoint(49.95, 44.245), OpticsPoint(49.995, 0.0))
        for (p in points) for (sx in listOf(-1, 1)) for (sy in listOf(-1, 1)) {
            assertTrue("inside $p $sx $sy", shape.contains(50 + sx * p.x, 50 + sy * p.y))
            assertFalse("outside $p $sx $sy", shape.contains(50 + sx * (p.x + 0.02), 50 + sy * (p.y + 0.02)))
        }
    }

    // Flutter 3.47.6 round_superellipse_unittests.cc:713-746.
    @Test fun officialSlimDiagonalContains() {
        val shape = AeroveSuperellipseGeometry.resolve(100.0, 100.0, 1.0, 99.0, 1.0, 99.0)
        assertTrue(shape.contains(50.0, 50.0))
        for (sx in listOf(-1, 1)) for (sy in listOf(-1, 1)) {
            assertFalse(shape.contains(50 + sx * 49.999, 50 + sy * 49.999))
        }
        for (s in listOf(-1, 1)) {
            assertTrue(shape.contains(50 + s * 49.70, 50 + s * 49.70))
            assertFalse(shape.contains(50 + s * 49.72, 50 + s * 49.72))
        }
        val points = listOf(OpticsPoint(-40.0, -49.59), OpticsPoint(-20.0, -45.64),
            OpticsPoint(0.0, -37.01), OpticsPoint(20.0, -21.96), OpticsPoint(21.05, -20.92), OpticsPoint(40.0, 5.68))
        for (p in points) for (s in listOf(-1, 1)) {
            assertTrue(shape.contains(50 + s * p.x, 50 + s * p.y))
            assertFalse(shape.contains(50 + s * (p.x + 0.02), 50 + s * (p.y - 0.02)))
        }
    }

    @Test fun officialSharpCornerRegression() {
        val shape = AeroveSuperellipseGeometry.resolve(98.0, 28.0, 0.0, 3.0, 3.0, 0.0)
        assertFalse(shape.quadrants.all { it.contains(OpticsPoint(147.0 - 196.0, 14.0)) })
    }

    @Test fun radiusNormalizationKeepsOfficialWeightedSplits() {
        val shape = AeroveSuperellipseGeometry.resolve(100.0, 40.0, 8.0, 1000.0, 1000.0, 8.0)
        assertEquals(0.16, shape.radii[0], 1e-12)
        assertEquals(20.0, shape.radii[1], 1e-12)
        assertEquals(100 * 8.0 / 1008, shape.quadrants[0].origin.x, 1e-12)
        assertEquals(20.0, shape.quadrants[0].origin.y, 1e-12)
    }

    @Test fun circleLimitAndCurvesAreFinite() {
        val circle = AeroveSuperellipseGeometry.resolve(40.0, 40.0, 1000.0)
        assertEquals(2.0, circle.quadrants[0].along.n, 0.0)
        assertEquals(20.0, circle.quadrants[0].along.radius, 1e-9)
        assertEquals(48, circle.curveUniforms().size)
        assertEquals(16, circle.quadrantUniforms().size)
        for (shape in listOf(circle, AeroveSuperellipseGeometry.resolve(400.0, 48.0, 0.0),
            AeroveSuperellipseGeometry.resolve(400.0, 48.0, 16.0, 8.0))) {
            assertTrue(shape.curveUniforms().all { it.isFinite() })
            val segments = shape.segments()
            assertTrue(segments.isNotEmpty())
            assertTrue(segments.filterIsInstance<SuperellipseSegment.Conic>().all { it.weight.isFinite() && it.weight > 0 })
        }
    }

    @Test fun uniformContourIsMirroredAndInsetCrossesOfficialBoundary() {
        val shape = AeroveSuperellipseGeometry.resolve(100.0, 100.0, 5.0)
        for (p in listOf(OpticsPoint(48.53, 48.53), OpticsPoint(45.72, 49.87))) {
            for (sx in listOf(-1, 1)) for (sy in listOf(-1, 1)) {
                assertTrue(shape.cornerInset(50 + sx * p.x, 50 + sy * p.y) > 0)
                assertTrue(shape.cornerInset(50 + sx * (p.x + 0.02), 50 + sy * (p.y + 0.02)) < 0)
            }
        }
        assertTrue(abs(shape.cornerInset(50.0, 0.0)) < 1e-9)
    }
}
